/* The browser explores Python-generated results. SQL, training and source refresh happen at build time. */
(() => {
'use strict';
const D=JSON.parse(document.getElementById('dashboard-data').textContent),$=id=>document.getElementById(id);
const HAS_WEBGL=(()=>{try{const c=document.createElement('canvas');return !!(c.getContext('webgl2')||c.getContext('webgl'));}catch{return false;}})();
const GREEN='#164e40',GOLD='#d2a15a',MINT='#b8d8b4',BLUE='#7598b2',INK='#20342d',SOFT='#829087';
const state={view:'overview',period:'ytd',market:'all',segment:'All customers',selected:null,productLimit:7,model:'forest',threshold:.5,surfaceMode:HAS_WEBGL?'3d':'contour'};
const money=(n,d=0)=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:d}).format(n);
const compact=n=>Math.abs(n)>=1e6?'£'+(n/1e6).toFixed(2)+'m':Math.abs(n)>=1e3?'£'+(n/1e3).toFixed(0)+'k':money(n);
const num=n=>new Intl.NumberFormat('en-GB',{maximumFractionDigits:0}).format(n);
const pct=(n,d=1)=>(n*100).toFixed(d)+'%';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const smallScreen=()=>matchMedia('(max-width:640px)').matches;
const chartConfig={responsive:true,displaylogo:false,scrollZoom:false,displayModeBar:smallScreen()?false:'hover',modeBarButtonsToRemove:['sendDataToCloud','autoScale2d','toggleSpikelines'],toImageButtonOptions:{format:'png',scale:2}};
function layout(extra={}){return {template:'none',paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',font:{family:'Inter, Arial, sans-serif',size:10,color:SOFT},margin:{l:45,r:20,t:20,b:40},showlegend:false,hoverlabel:{bgcolor:'#fff',font:{color:INK,size:12}},xaxis:{showgrid:false,zeroline:false,automargin:true,tickfont:{size:9}},yaxis:{gridcolor:'#e9ede7',zeroline:false,automargin:true,tickfont:{size:9}},...extra};}
function plot(id,data,lay={}){return Plotly.react($(id),data,layout(lay),chartConfig);}
function fromPython(id,fig){const f=structuredClone(fig);f.layout.height=$(id).clientHeight;return Plotly.react($(id),f.data,f.layout,chartConfig);}
function metric(name,value,note,icon='↗'){return `<div class="metric"><div class="metric-name">${esc(name)}<span class="metric-icon" aria-hidden="true">${icon}</span></div><strong class="metric-value">${esc(value)}</strong><div class="metric-note">${note}</div></div>`;}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3000);}
const HEADERS={overview:['','Bottom lines, plotted','','Commerce'],customers:['','Customers','','Customers'],affinity:['','What sells together','','Bought together'],clusters:['','Customer clustering','','Clustering'],models:['','Repeat purchase model','','Classification'],data:['','Follow the data','','Data & logic']};
function showView(view,scroll=true){if(!HEADERS[view])return;if(scroll){try{const P=window.parent;if(P!==window&&P.plausible)P.plausible('Demo tab',{props:{tab:HEADERS[view][3]}});}catch(e){}}state.view=view;document.querySelectorAll('.view').forEach(e=>e.classList.toggle('active',e.id==='view-'+view));document.querySelectorAll('.nav-item').forEach(e=>{e.classList.toggle('active',e.dataset.view===view);e.setAttribute('aria-current',e.dataset.view===view?'page':'false');});const [eye,title,sub,name]=HEADERS[view];$('pageEyebrow').textContent=eye;$('pageTitle').innerHTML=title;$('pageSubtitle').textContent=sub;$('breadcrumb').textContent=name;history.replaceState(null,'','#'+view);if(scroll)window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});({overview:renderOverview,customers:renderCustomers,affinity:renderAffinity,forecast:renderForecast,models:renderModels,regression:renderRegression,clusters:renderClusters,data:renderData})[view]();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b){e.preventDefault();showView(b.dataset.view);}const q=e.target.closest('[data-sql]');if(q)openSql(q.dataset.sql);});
function current(){return D.overview[state.period+'_'+state.market];}
function delta(now,prior){return prior?(now/prior-1):null;}
function renderOverview(){const v=current(),s=v.summary,pr=v.previous,change=pr?delta(s.net,pr.net):null;state.productLimit=7;
$('filterMeta').textContent=num(s.countries)+' countries · '+num(s.orders)+' purchase invoices';
$('netRevenue').textContent=compact(s.net);$('netRevenue').title=money(s.net,2);
$('netChange').innerHTML=change!==null?`<strong>${change>=0?'↗':'↘'} ${pct(Math.abs(change))}</strong><span>vs the same dates in 2010</span>`:'<span>All complete months in the source</span>';
$('heroNarrative').textContent=`${money(s.gross,0)} in gross merchandise sales, less ${money(s.credits,0)} in credits.`;
fromPython('revenueChart',v.trend);fromPython('flowChart',v.flow);
const orderChange=pr?delta(s.orders,pr.orders):null;const aov=s.gross/s.orders;const identified=s.identified_gross/s.gross;
$('commerceMetrics').innerHTML=metric('Purchase invoices',num(s.orders),orderChange!==null?`<span class="positive">${orderChange>=0?'+':'−'}${pct(Math.abs(orderChange))}</span> vs prior-year dates`:'Positive merchandise invoices','▤')+metric('Average order value',money(aov,0),'Gross sales ÷ purchase invoices','◈')+metric('Credit / gross',pct(s.credits/s.gross),'Credits by posting date, not matched returns','↶')+metric('Known customers',num(s.customers),pct(identified,0)+' of gross sales have a customer ID','♧');
$('flowNote').textContent=`${money(v.flow_total,0)} reconciled across every stage. Anonymous sales are excluded from this flow.`;
renderMap(v.countries);renderProducts();
}
$('periodFilter').addEventListener('change',e=>{state.period=e.target.value;renderOverview();});$('marketFilter').addEventListener('change',e=>{state.market=e.target.value;renderOverview();});
function renderProducts(){const v=current(),needle=$('productSearch').value.toLowerCase(),products=v.products.filter(p=>(p.description+' '+p.stock_code).toLowerCase().includes(needle));$('productRows').innerHTML=products.slice(0,state.productLimit).map((p,i)=>`<tr><td class="product-name" title="${esc(p.description)}"><span class="product-rank">${String(i+1).padStart(2,'0')}</span>${esc(p.description)}<span class="product-sku">${esc(p.stock_code)}</span></td><td>${money(p.net)}</td><td>${num(p.units)}</td><td>${num(p.orders)}</td><td>${pct(p.credits/p.gross)}</td><td><span class="share-bar"><i style="width:${Math.max(2,Math.min(100,p.net/v.summary.net*100*7))}%"></i></span>${pct(p.net/v.summary.net)}</td></tr>`).join('')||'<tr><td colspan="6">No matching products in the top 100.</td></tr>';$('moreProducts').hidden=products.length<=state.productLimit;}
$('productSearch').addEventListener('input',renderProducts);$('moreProducts').addEventListener('click',()=>{state.productLimit+=15;renderProducts();});
const CENTRES={'United Kingdom':[-2,54],'Germany':[10,51],'France':[2,47],'EIRE':[-8,53],'Netherlands':[5,52],'Spain':[-4,40],'Australia':[134,-25],'Switzerland':[8,47],'Belgium':[4,50],'Portugal':[-8,40],'Norway':[9,61],'Sweden':[16,62],'Denmark':[10,56],'Finland':[25,64],'Italy':[12,43],'Austria':[14,47],'Cyprus':[33,35],'Japan':[138,37],'Singapore':[104,1],'USA':[-100,39],'Canada':[-105,55],'Poland':[19,52],'Greece':[23,39],'Israel':[35,31],'United Arab Emirates':[54,24],'Hong Kong':[114,22],'Iceland':[-19,65],'Malta':[14,36],'Lithuania':[24,55]};
const MAP_ALIAS={'EIRE':'Ireland','USA':'United States of America','RSA':'South Africa','Korea':'South Korea','Czech Republic':'Czechia'};
Object.assign(CENTRES,{'Channel Islands':[-2.3,49.4],'RSA':[24,-29],'Brazil':[-52,-10],'Bahrain':[50.5,26],'Korea':[128,36],'Czech Republic':[15.5,49.8],'Lebanon':[35.8,33.9],'Saudi Arabia':[45,24],'Thailand':[101,15],'Nigeria':[8,9.5],'Bermuda':[-64.8,32.3],'West Indies':[-61,15]});
let mapData={},mapTotal=1;
const shade=t=>{const a=[233,238,227],b=[22,78,64];return 'rgb('+a.map((v,i)=>Math.round(v+(b[i]-v)*(.15+t*.8))).join(',')+')';};
function renderMap(countries){$('worldMap').innerHTML=D.world;const pos=countries.filter(c=>c.net>0),max=Math.max(...pos.map(c=>c.net)),lmin=Math.log10(Math.min(...pos.map(c=>c.net))),lmax=Math.log10(max);mapTotal=pos.reduce((a,c)=>a+c.net,0);mapData={};pos.forEach(c=>mapData[c.country]=c);$('marketSubtitle').textContent=pos.length+' countries with positive net sales';const svg=mapSvg();
pos.forEach(c=>{const p=svg.querySelector(`path[data-name="${CSS.escape(MAP_ALIAS[c.country]||c.country)}"]`);if(p){p.classList.add('has-sales');p.dataset.country=c.country;p.style.fill=shade((Math.log10(c.net)-lmin)/((lmax-lmin)||1));}});
$('mapDots').innerHTML=pos.filter(c=>CENTRES[c.country]).map(c=>{const [lon,lat]=CENTRES[c.country];const r0=2.5+Math.sqrt(c.net/max)*8;return `<circle class="map-dot" data-country="${esc(c.country)}" data-r="${r0}" cx="${(lon+180)/360*680}" cy="${(85-lat)/165*300}" r="${r0}"></circle>`;}).join('');
setMapView();bindMap();$('marketRanking').innerHTML=pos.slice(0,5).map(c=>`<div class="map-rank" data-country="${esc(c.country)}"><span><i class="flag-marker"></i>${esc(c.country)}</span><b>${compact(c.net)}</b></div>`).join('');}
function mapHot(country){const box=$('worldMap');box.querySelectorAll('.is-hot').forEach(e=>e.classList.remove('is-hot'));document.querySelectorAll('.map-rank.is-hot').forEach(e=>e.classList.remove('is-hot'));if(!country)return;box.querySelectorAll(`[data-country="${CSS.escape(country)}"]`).forEach(e=>{e.classList.add('is-hot');if(e.tagName==='circle')e.parentNode.appendChild(e);});document.querySelectorAll(`.map-rank[data-country="${CSS.escape(country)}"]`).forEach(e=>e.classList.add('is-hot'));}
function mapTip(country,name,x,y){const tip=$('mapTip');if(!country&&!name){tip.hidden=true;return;}const c=mapData[country];tip.innerHTML=c?`<strong>${esc(c.country)}</strong><dl><dt>Net sales</dt><dd>${money(c.net)}</dd><dt>Share</dt><dd>${pct(c.net/mapTotal)}</dd><dt>Orders</dt><dd>${num(c.orders)}</dd><dt>Customers</dt><dd>${num(c.customers)}</dd></dl>`:`<strong>${esc(name)}</strong><span class="map-tip-none">No sales in this view</span>`;tip.hidden=false;const wrap=tip.parentNode.getBoundingClientRect(),w=tip.offsetWidth,h=tip.offsetHeight;let left=x-wrap.left+14,top=y-wrap.top+14;if(left+w>wrap.width-4)left=x-wrap.left-w-14;if(top+h>wrap.height-4)top=Math.max(4,y-wrap.top-h-14);tip.style.left=Math.max(4,left)+'px';tip.style.top=top+'px';}
function mapCentre(country){if(CENTRES[country]){const [lon,lat]=CENTRES[country];return [(lon+180)/360*680,(85-lat)/165*300];}const p=$('worldMap').querySelector(`path[data-country="${CSS.escape(country)}"]`);if(!p)return null;const b=p.getBBox();return [b.x+b.width/2,b.y+b.height/2];}
let mapAnim=0;function animateMap(target){cancelAnimationFrame(mapAnim);const from={...mapView},t0=performance.now(),dur=matchMedia('(prefers-reduced-motion:reduce)').matches?0:420;const step=t=>{const k=dur?Math.min(1,(t-t0)/dur):1,e=1-Math.pow(1-k,3);for(const key of ['x','y','w','h'])mapView[key]=from[key]+(target[key]-from[key])*e;setMapView();if(k<1)mapAnim=requestAnimationFrame(step);};mapAnim=requestAnimationFrame(step);}
function zoomToCountry(country){const c=mapCentre(country);if(!c)return;const w=Math.min(mapView.w,MW/4),h=w*MH/MW;const t={x:Math.min(Math.max(c[0]-w/2,0),MW-w),y:Math.min(Math.max(c[1]-h/2,0),MH-h),w,h};animateMap(t);}

/* Zoomable map: buttons, double-click, ctrl/⌘ + scroll or trackpad pinch, touch pinch, drag to pan. */
const MW=680,MH=300,mapView={x:0,y:0,w:MW,h:MH};let mapBound=false;
function mapSvg(){return $('worldMap').querySelector('svg');}
function setMapView(){const svg=mapSvg();if(!svg)return;svg.setAttribute('viewBox',`${mapView.x} ${mapView.y} ${mapView.w} ${mapView.h}`);const k=MW/mapView.w;svg.querySelectorAll('.map-dot').forEach(d=>d.setAttribute('r',d.dataset.r/Math.pow(k,.75)*(d.classList.contains('is-hot')?1.35:1)));$('worldMap').classList.toggle('zoomed',k>1.01);$('mapReset').hidden=k<=1.01;$('mapOut').disabled=k<=1.01;$('mapIn').disabled=k>=11.9;}
function clampMap(){mapView.x=Math.min(Math.max(mapView.x,0),MW-mapView.w);mapView.y=Math.min(Math.max(mapView.y,0),MH-mapView.h);}
function zoomMap(f,cx=mapView.x+mapView.w/2,cy=mapView.y+mapView.h/2){const w=Math.min(MW,Math.max(MW/12,mapView.w/f)),h=w*MH/MW,fx=(cx-mapView.x)/mapView.w,fy=(cy-mapView.y)/mapView.h;mapView.x=cx-fx*w;mapView.y=cy-fy*h;mapView.w=w;mapView.h=h;clampMap();setMapView();}
function mapPoint(e){const svg=mapSvg(),p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());}
function bindMap(){if(mapBound)return;mapBound=true;const box=$('worldMap'),pts=new Map();let last=null,pinch=null;
$('mapIn').addEventListener('click',()=>zoomMap(1.6));$('mapOut').addEventListener('click',()=>zoomMap(1/1.6));$('mapReset').addEventListener('click',()=>animateMap({x:0,y:0,w:MW,h:MH}));
box.addEventListener('dblclick',e=>{if(!mapSvg())return;const p=mapPoint(e);zoomMap(e.shiftKey?1/2:2,p.x,p.y);});
box.addEventListener('wheel',e=>{if(!(e.ctrlKey||e.metaKey)||!mapSvg())return;e.preventDefault();const p=mapPoint(e);zoomMap(Math.exp(-e.deltaY*.01),p.x,p.y);},{passive:false});
box.addEventListener('pointerdown',e=>{if(!mapSvg())return;pts.set(e.pointerId,e);if(pts.size===1&&MW/mapView.w>1.01){last=e;box.setPointerCapture(e.pointerId);}if(pts.size===2){const [a,b]=[...pts.values()];pinch={d:Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY)};}});
box.addEventListener('pointermove',e=>{if(!pts.has(e.pointerId))return;pts.set(e.pointerId,e);if(pts.size===2&&pinch){const [a,b]=[...pts.values()],d=Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY),mid=mapPoint({clientX:(a.clientX+b.clientX)/2,clientY:(a.clientY+b.clientY)/2});zoomMap(d/pinch.d,mid.x,mid.y);pinch.d=d;return;}
 if(last){const r=mapSvg().getBoundingClientRect();mapView.x-=(e.clientX-last.clientX)/r.width*mapView.w;mapView.y-=(e.clientY-last.clientY)/r.height*mapView.h;last=e;clampMap();setMapView();}});
let downAt=null;box.addEventListener('pointerdown',e=>{downAt=[e.clientX,e.clientY];},true);box.addEventListener('pointermove',e=>{if(pts.size>1||(last&&downAt)){mapTip();return;}const t=e.target.closest('[data-country],path[data-name]');if(!t||!box.contains(t)){mapHot();mapTip();return;}const c=t.dataset.country;mapHot(c);mapTip(c,t.dataset.name,e.clientX,e.clientY);});box.addEventListener('pointerleave',()=>{mapHot();mapTip();});box.addEventListener('click',e=>{const moved=downAt&&Math.hypot(e.clientX-downAt[0],e.clientY-downAt[1])>5;downAt=null;if(moved)return;const t=e.target.closest('[data-country]');if(t){mapHot(t.dataset.country);mapTip(t.dataset.country,null,e.clientX,e.clientY);zoomToCountry(t.dataset.country);}});const rank=$('marketRanking');rank.addEventListener('mouseover',e=>{const r=e.target.closest('[data-country]');mapHot(r?r.dataset.country:null);});rank.addEventListener('mouseleave',()=>mapHot());rank.addEventListener('click',e=>{const r=e.target.closest('[data-country]');if(r){mapHot(r.dataset.country);zoomToCountry(r.dataset.country);}});$('mapReset').addEventListener('click',()=>{mapTip();mapHot();});const end=e=>{pts.delete(e.pointerId);if(pts.size<2)pinch=null;if(!pts.size)last=null;};['pointerup','pointercancel','pointerleave'].forEach(t=>box.addEventListener(t,end));}
/* Customer workbench. */
let customerBound=false;
function filteredCustomers(){let a=D.customers;if(state.segment!=='All customers')a=a.filter(c=>c.segment===state.segment);if(state.selected)a=a.filter(c=>state.selected.has(c.customer_id));return a;}
function renderCustomers(){const all=D.customers,segments=Object.keys(D.colors);$('segmentControls').innerHTML=['All customers',...segments].map(s=>`<button class="segment-chip ${s===state.segment?'active':''}" data-segment="${esc(s)}" aria-pressed="${s===state.segment}"><i style="background:${D.colors[s]||GREEN}"></i>${esc(s)} <span>${num(s==='All customers'?all.length:all.filter(c=>c.segment===s).length)}</span></button>`).join('');
const traces=segments.map(s=>{const a=all.filter(c=>c.segment===s);return {type:HAS_WEBGL?'scattergl':'scatter',mode:'markers',name:s,x:a.map(c=>c.recency),y:a.map(c=>c.frequency),customdata:a.map(c=>[c.customer_id,c.monetary,c.segment,c.country]),text:a.map(c=>'Customer '+c.customer_id),marker:{color:D.colors[s],size:a.map(c=>Math.min(30,Math.max(5,Math.log10(c.monetary+1)*3.2))),opacity:s===state.segment||state.segment==='All customers'?.65:.08,line:{width:0}},hovertemplate:'%{text}<br>%{customdata[2]} · %{customdata[3]}<br>%{x} days since purchase · %{y} orders<br>Historic gross £%{customdata[1]:,.0f}<extra></extra>'};});
plot('customerScatter',traces,{height:smallScreen()?310:360,dragmode:'lasso',xaxis:{title:{text:'Days since last purchase',font:{size:10}},autorange:'reversed',gridcolor:'#eef1e9',zeroline:false},yaxis:{title:{text:'Purchase invoices (log scale)',font:{size:10}},type:'log',tickvals:[1,2,5,10,20,50,100,200,500],ticktext:['1','2','5','10','20','50','100','200','500'],gridcolor:'#eef1e9',zeroline:false},margin:{l:58,r:20,t:15,b:50},hovermode:'closest'}).then(()=>{if(!customerBound){$('customerScatter').on('plotly_selected',ev=>{state.selected=ev?.points?.length?new Set(ev.points.map(p=>p.customdata[0])):null;renderCustomerTable();});$('customerScatter').on('plotly_click',ev=>{state.selected=new Set([ev.points[0].customdata[0]]);renderCustomerTable();});customerBound=true;}});
const vals=segments.map(s=>all.filter(c=>c.segment===s).reduce((n,c)=>n+c.monetary,0));plot('segmentChart',[{type:'pie',labels:segments,values:vals,hole:.72,textinfo:'none',sort:false,marker:{colors:segments.map(s=>D.colors[s]),line:{color:'#fff',width:3}},hovertemplate:'%{label}<br>£%{value:,.0f} · %{percent}<extra></extra>'}],{height:230,margin:{l:18,r:18,t:15,b:10},annotations:[{text:num(all.length),x:.5,y:.53,showarrow:false,font:{size:25,color:INK}},{text:'known customers',x:.5,y:.4,showarrow:false,font:{size:9,color:SOFT}}]});
$('segmentKey').innerHTML=segments.map((s,i)=>`<div><i style="background:${D.colors[s]}"></i>${esc(s)}<b>${compact(vals[i])}</b></div>`).join('');fromPython('cohortChart',D.cohort.figure);renderCustomerTable();}
function renderCustomerTable(){const a=filteredCustomers(),spend=a.reduce((n,c)=>n+c.monetary,0),repeat=a.filter(c=>c.frequency>1).length,risk=a.filter(c=>c.segment==='At risk').length;$('customerMetrics').innerHTML=metric('Customers in view',num(a.length),state.selected?'Selected in the customer map':'As at 30 Nov 2011','♧')+metric('Historic gross sales',compact(spend),'Full available customer history','↗')+metric('Repeat purchasers',pct(a.length?repeat/a.length:0),'More than one purchase invoice','↻')+metric('At-risk relationships',num(risk),'3+ invoices · inactive for 90+ days','◷');$('selectionNote').textContent=state.selected?`${num(a.length)} customers selected. The table and metrics follow your selection.`:'Drag to select a group. Click a point to inspect a customer.';$('customerTableNote').textContent=(state.selected?'Selected customers':'Highest-value '+(state.segment==='All customers'?'identified customers':state.segment.toLowerCase()))+' · showing up to 25';$('customerRows').innerHTML=a.slice(0,25).map(c=>`<tr><td>Customer ${esc(c.customer_id)}</td><td><span class="segment-pill">${esc(c.segment)}</span></td><td>${esc(c.country)}</td><td>${num(c.frequency)}</td><td>${money(c.monetary)}</td><td>${num(c.recency)}</td></tr>`).join('')||'<tr><td colspan="6">No customers in this selection.</td></tr>';$('clearCustomerSelection').hidden=!state.selected;}
$('segmentControls').addEventListener('click',e=>{const b=e.target.closest('[data-segment]');if(b){state.segment=b.dataset.segment;state.selected=null;renderCustomers();}});$('clearCustomerSelection').addEventListener('click',()=>{state.selected=null;renderCustomerTable();Plotly.restyle($('customerScatter'),{selectedpoints:[null]});});
/* Real model outputs, evaluated at a user-selected decision threshold. */
function confusion(m,t){const c={tp:0,fp:0,tn:0,fn:0};m.actual.forEach((v,i)=>c[v?(m.scores[i]>=t?'tp':'fn'):(m.scores[i]>=t?'fp':'tn')]++);return c;}
function renderModels(){const m=D.models[state.model],c=confusion(m,state.threshold),positive=c.tp+c.fn,negative=c.fp+c.tn,precision=c.tp/(c.tp+c.fp)||0,recall=c.tp/positive,fpRate=c.fp/negative,f1=2*c.tp/(2*c.tp+c.fp+c.fn),accuracy=(c.tp+c.tn)/m.actual.length;
$('thresholdValue').textContent=state.threshold.toFixed(2);$('thresholdNote').textContent=num(c.tp+c.fp)+' customers flagged · '+num(m.actual.length)+' evaluated';$('aucBadge').textContent='AUC '+m.metrics.auc.toFixed(3);$('apBadge').textContent='AP '+m.metrics.ap.toFixed(3);
$('modelMetrics').innerHTML=metric('ROC AUC',m.metrics.auc.toFixed(3),'Ranking across thresholds','↗')+metric('Precision',pct(precision),'Flagged customers who repeated','◈')+metric('Recall',pct(recall),'Repeat buyers detected','◎')+metric('F1 score',f1.toFixed(3),'Precision–recall balance','◇')+metric('Accuracy',pct(accuracy),'Correct classifications','✓')+metric('Brier score',m.metrics.brier.toFixed(3),'Probability error · lower is better','◷');
const marker={type:'scatter',mode:'markers',x:[fpRate],y:[recall],marker:{color:'#fff',size:11,line:{color:GOLD,width:3}},hovertemplate:'Your threshold<br>False positive rate %{x:.1%}<br>Recall %{y:.1%}<extra></extra>'};
const axes={xaxis:{title:{text:'False positive rate',font:{size:10}},range:[0,1],tickformat:'.0%',showgrid:false,zeroline:false},yaxis:{title:{text:'True positive rate',font:{size:10}},range:[0,1.04],tickformat:'.0%',gridcolor:'#edf0e8',zeroline:false}};
plot('rocChart',[{type:'scatter',mode:'lines',x:[0,1],y:[0,1],line:{color:'#b6c1b1',dash:'dot',width:1},hoverinfo:'skip'},{type:'scatter',mode:'lines',x:m.roc.x,y:m.roc.y,line:{color:GREEN,width:2.5},fill:'tozeroy',fillcolor:'#eaf1e580',hovertemplate:'FPR %{x:.1%}<br>Recall %{y:.1%}<extra></extra>'},marker],{height:310,...axes,margin:{l:60,r:24,t:18,b:50}});
plot('prChart',[{type:'scatter',mode:'lines',x:[0,1],y:[D.model_meta.prevalence,D.model_meta.prevalence],line:{color:'#b6c1b1',dash:'dot',width:1},hoverinfo:'skip'},{type:'scatter',mode:'lines',x:m.pr.x,y:m.pr.y,line:{color:GREEN,width:2.3},hovertemplate:'Recall %{x:.1%}<br>Precision %{y:.1%}<extra></extra>'},{...marker,x:[recall],y:[precision]}],{height:310,...axes,xaxis:{...axes.xaxis,title:{text:'Recall',font:{size:10}}},yaxis:{...axes.yaxis,title:{text:'Precision',font:{size:10}}},margin:{l:60,r:24,t:18,b:50}});
$('confusionMatrix').innerHTML=`<table class="matrix"><caption class="sr-only">Actual outcomes by model prediction</caption><thead><tr><td></td><th scope="col">Predicted<br>repeat</th><th scope="col">Predicted<br>no repeat</th></tr></thead><tbody><tr><th scope="row">Actually<br>repeated</th><td class="correct"><strong>${num(c.tp)}</strong><span>True positive</span></td><td class="wrong"><strong>${num(c.fn)}</strong><span>False negative</span></td></tr><tr><th scope="row">Did not<br>repeat</th><td class="wrong"><strong>${num(c.fp)}</strong><span>False positive</span></td><td class="correct"><strong>${num(c.tn)}</strong><span>True negative</span></td></tr></tbody></table><p class="matrix-caption">${num(positive)} repeated · ${num(negative)} did not · threshold ${state.threshold.toFixed(2)}</p>`;
plot('importanceChart',[{type:'bar',orientation:'h',x:m.importance.map(x=>x.value).reverse(),y:m.importance.map(x=>x.feature).reverse(),marker:{color:m.importance.map((_,i)=>i===0?GREEN:'#a7c49a').reverse()},hovertemplate:'%{y}<br>AUC decrease %{x:.4f}<extra></extra>'}],{height:310,margin:{l:115,r:25,t:15,b:40},xaxis:{title:{text:'Mean ROC AUC decrease',font:{size:9}},gridcolor:'#edf0e8',zeroline:true,zerolinecolor:'#ced8c6'},yaxis:{showgrid:false,tickfont:{size:9}},bargap:.35});
const mm=D.model_meta;$('modelMethod').innerHTML=`<dl><dt>Prediction target</dt><dd>${esc(mm.label)}</dd><dt>Training snapshot</dt><dd>${mm.train_cutoff} · ${num(mm.train_n)} customers</dd><dt>Evaluation snapshot</dt><dd>${mm.test_cutoff} · ${num(mm.test_n)} customers</dd><dt>Outcome window</dt><dd>90 days from the cutoff, exclusive of the end date</dd><dt>Positive class rate</dt><dd>${pct(mm.prevalence)} in the held-out snapshot</dd><dt>Features</dt><dd>${mm.features.map(x=>esc(x.replaceAll('_',' '))).join(', ')}</dd></dl><p>${esc(mm.note)} Numeric features are log-transformed. ROC AUC, average precision and Brier score do not change with the decision threshold. Permutation importance is measured on the held-out snapshot, not presented as causal influence.</p>`;renderModelContext();
}
function renderModelContext(){const mm=D.model_meta,a=D.models[state.model],bl=[...mm.baselines.slice(0,4)].map(x=>({n:x.feature.replaceAll('_',' ')+' alone',v:x.auc})).concat([{n:(state.model==='forest'?'Random forest':'Logistic regression')+' (all features)',v:a.metrics.auc},{n:'Same model, customers unseen in training',v:a.metrics.unseen_auc}]).reverse();
plot('baselineChart',[{type:'bar',orientation:'h',x:bl.map(x=>x.v),y:bl.map(x=>x.n),marker:{color:bl.map(x=>x.n.startsWith('Random')||x.n.startsWith('Logistic')?GREEN:x.n.startsWith('Same')?GOLD:'#b9c8b4')},text:bl.map(x=>x.v.toFixed(3)),textposition:'outside',cliponaxis:false,hovertemplate:'%{y}<br>AUC %{x:.3f}<extra></extra>'}],{height:260,margin:{l:230,r:50,t:10,b:36},xaxis:{range:[.5,.8],gridcolor:'#edf0e8',zeroline:false,title:{text:'ROC AUC · higher is better',font:{size:9}}},yaxis:{showgrid:false,tickfont:{size:9}},bargap:.4});
}

$('modelSelect').addEventListener('change',e=>{state.model=e.target.value;renderModels();});let thresholdFrame;$('thresholdSlider').addEventListener('input',e=>{state.threshold=Number(e.target.value);cancelAnimationFrame(thresholdFrame);thresholdFrame=requestAnimationFrame(renderModels);});

/* Products bought together: lift and confidence from SQL, plus a second-year check. */
const shortName=(n,l=38)=>n.length>l?n.slice(0,l-1)+'…':n;
function renderAffinity(){const a=D.affinity,st=a.stability;
$('affinityMetrics').innerHTML=metric('Baskets analysed',num(a.baskets),'Purchase invoices, '+a.period,'▤')+metric('Products with a pattern',num(a.products),'Seen in 40+ baskets','◈')+metric('Pairs found',num(a.pairs),'Together in 40+ baskets','◎')+metric('Held up in 2011',pct(st.kept_share,0),num(st.kept)+' of '+num(st.eligible)+' strongest 2010 pairs','✓');
const sel=$('affinitySelect');if(!sel.options.length){sel.innerHTML=a.picker.map((p,i)=>`<option value="${i}">${esc(shortName(p.name,46))}</option>`).join('');}
const p=a.picker[Number(sel.value)||0],pr=[...p.partners].reverse();
plot('partnerChart',[{type:'bar',orientation:'h',x:pr.map(x=>x.conf*100),y:pr.map(x=>shortName(x.name)),text:pr.map(x=>x.lift.toFixed(1)+'× chance'),textposition:'outside',cliponaxis:false,marker:{color:GREEN},customdata:pr.map(x=>[x.together,x.lift]),hovertemplate:'%{y}<br>In %{x:.0f}% of baskets with this product<br>%{customdata[0]} baskets together · %{customdata[1]:.1f}× chance<extra></extra>'}],{height:310,margin:{l:215,r:70,t:10,b:40},xaxis:{title:{text:'% of this product’s baskets that also hold it',font:{size:9}},gridcolor:'#edf0e8',zeroline:false,ticksuffix:'%'},yaxis:{showgrid:false,tickfont:{size:9}},bargap:.4});
const t=a.top.slice(0,12).reverse();
plot('pairChart',[{type:'bar',orientation:'h',x:t.map(x=>x.together),y:t.map(x=>shortName(x.a,30)+' + '+shortName(x.b,30)),marker:{color:'#6b9e85'},customdata:t.map(x=>[x.lift,x.share]),hovertemplate:'%{y}<br>%{x} baskets · %{customdata[0]:.1f}× chance<extra></extra>'}],{height:310,margin:{l:330,r:20,t:10,b:40},xaxis:{title:{text:'Baskets containing both',font:{size:9}},gridcolor:'#edf0e8',zeroline:false},yaxis:{showgrid:false,tickfont:{size:8}},bargap:.35});
}
$('affinitySelect').addEventListener('change',renderAffinity);
/* Forecast: same week last year, scaled by growth over the last 8 weeks, scored on weeks it had not seen. */
function renderForecast(){const f=D.forecast,b=f.backtest,w=f.forward,r=b.rolling;
const vs=w.total/w.last_year_total-1;
$('forecastMetrics').innerHTML=metric('Next 13 weeks',compact(w.total),'From '+w.start+' · '+(vs>=0?'+':'')+pct(vs)+' vs the same weeks last year','↗')+metric('Likely range',compact(w.low)+' – '+compact(w.high),'80% of past quarters fell inside this kind of range','◎')+metric('Backtest quarter',(b.plotline.total_error>=0?'+':'')+pct(b.plotline.total_error),'Total error for '+b.origin+' + 13 weeks','◇')+metric('Typical weekly error',pct(b.plotline.mape,0),'Weeks vary a lot · '+pct(b.coverage,0)+' landed in the range','◷');
fromPython('forecastChart',f.figure);
const row=(n,m)=>`<tr><td>${n}</td><td>${pct(m.mape,0)}</td><td>${(m.total_error>=0?'+':'')+pct(m.total_error)}</td></tr>`;
$('forecastRows').innerHTML=row('Plotline forecast (last year × growth)',b.plotline)+row('Same week last year',b.last_year)+row('Flat: average of last 8 weeks',b.flat);
}

/* Regression: expected 90-day spend = chance of buying x spend if they buy. */
function renderRegression(){const r=D.regression;
$('regMetrics').innerHTML=metric('Typical error',money(r.mae),'Mean absolute error per customer','◷')+metric('Predicted total',compact(r.total_pred),'Actual '+compact(r.total_actual),'Σ')+metric('Top 10% of predictions',pct(r.capture,0),'Share of actual spend they made','◎')+metric('Fit among buyers',r.r2_buyers.toFixed(2),'R² on log spend · past spend alone '+r.r2_buyers_past.toFixed(2),'↗');
const d=r.deciles,lab=d.map(x=>String(x.bin+1));
plot('regDecile',[{type:'bar',name:'Predicted',x:lab,y:d.map(x=>x.predicted),marker:{color:'#b9c8b4'},hovertemplate:'Tenth %{x}<br>Predicted £%{y:,.0f}<extra></extra>'},{type:'bar',name:'Actual',x:lab,y:d.map(x=>x.actual),marker:{color:GREEN},hovertemplate:'Tenth %{x}<br>Actual £%{y:,.0f}<extra></extra>'}],{height:310,barmode:'group',bargap:.25,showlegend:true,legend:{orientation:'h',y:1.08,x:0,font:{size:9}},yaxis:{type:'log',tickprefix:'£',gridcolor:'#edf0e8',zeroline:false},xaxis:{title:{text:'Tenth of customers, lowest to highest prediction',font:{size:9}}},margin:{l:55,r:15,t:30,b:45}});
const sc=r.scatter,mx=Math.max(...sc.actual,...sc.pred);
plot('regScatter',[{type:'scatter',mode:'lines',x:[10,mx],y:[10,mx],line:{color:'#b6c1b1',dash:'dot',width:1},hoverinfo:'skip'},{type:'scatter',mode:'markers',x:sc.pred,y:sc.actual,marker:{color:GREEN,opacity:.35,size:5},hovertemplate:'Predicted £%{x:,.0f}<br>Actual £%{y:,.0f}<extra></extra>'}],{height:310,xaxis:{type:'log',title:{text:'Predicted if they buy',font:{size:9}},tickprefix:'£',showgrid:false},yaxis:{type:'log',title:{text:'Actual',font:{size:9}},tickprefix:'£',gridcolor:'#edf0e8',zeroline:false},margin:{l:60,r:15,t:15,b:45}});
const m=['Rank correlation','Top 10% capture','Fit among buyers (R²)'];
plot('regBaseline',[{type:'bar',name:'Past spend alone',x:m,y:[r.spearman_past,r.capture_past,r.r2_buyers_past],marker:{color:'#b9c8b4'},text:[r.spearman_past,r.capture_past,r.r2_buyers_past].map(v=>v.toFixed(2)),textposition:'outside',cliponaxis:false},{type:'bar',name:'Model',x:m,y:[r.spearman,r.capture,r.r2_buyers],marker:{color:GREEN},text:[r.spearman,r.capture,r.r2_buyers].map(v=>v.toFixed(2)),textposition:'outside',cliponaxis:false}],{height:310,barmode:'group',bargap:.3,showlegend:true,legend:{orientation:'h',y:1.08,x:0,font:{size:9}},yaxis:{range:[0,.8],gridcolor:'#edf0e8',zeroline:false},margin:{l:45,r:15,t:30,b:40},hovermode:false});
const im=[...r.importance].reverse();
plot('regImportance',[{type:'bar',orientation:'h',x:im.map(x=>x.value),y:im.map(x=>x.feature),marker:{color:im.map((_,i)=>i===im.length-1?GREEN:'#a7c49a')},hovertemplate:'%{y}<br>R² decrease %{x:.3f}<extra></extra>'}],{height:310,margin:{l:115,r:25,t:15,b:40},xaxis:{title:{text:'Mean R² decrease',font:{size:9}},gridcolor:'#edf0e8',zeroline:true,zerolinecolor:'#ced8c6'},yaxis:{showgrid:false,tickfont:{size:9}},bargap:.35});}
/* Clustering: k-means on log-scaled, standardised customer behaviour. */
const CLUSTER_COLORS=[GREEN,GOLD,BLUE,'#9dbfc1','#bfc4bc','#6b9e85','#c9a0a0','#7b8981'];
function renderClusters(){const c=D.clusters,best=c.by_k.find(x=>x.k===c.k),top=c.profiles[0];
$('clusterMetrics').innerHTML=metric('Groups found',String(c.k),'Best separation of 2 to 8','◈')+metric('Separation',best.silhouette.toFixed(2),'Silhouette score · −1 to 1','◎')+metric('Stability',pct(best.stability,0),'Agreement across resampled fits','✓')+metric(top.name,pct(top.share_spend,0)+' of spend',pct(top.share_customers,0)+' of customers','↗');
const names=c.profiles.map(p=>p.name);
plot('clusterScatter',names.map((n,i)=>{const ix=c.points.group.map((g,j)=>g===n?j:-1).filter(j=>j>=0);return {type:'scattergl',mode:'markers',name:n,x:ix.map(j=>c.points.x[j]),y:ix.map(j=>c.points.y[j]),marker:{color:CLUSTER_COLORS[i],size:4,opacity:.5},hovertemplate:n+'<extra></extra>'};}),{height:330,showlegend:true,legend:{orientation:'h',y:1.08,x:0,font:{size:9}},xaxis:{showticklabels:false,showgrid:false,zeroline:false},yaxis:{showticklabels:false,showgrid:false,zeroline:false},margin:{l:10,r:10,t:30,b:10}});
plot('clusterK',[{type:'scatter',mode:'lines+markers',name:'Separation',x:c.by_k.map(x=>x.k),y:c.by_k.map(x=>x.silhouette),line:{color:GREEN,width:2.4},marker:{size:c.by_k.map(x=>x.k===c.k?11:6),color:GREEN}},{type:'scatter',mode:'lines+markers',name:'Stability',yaxis:'y2',x:c.by_k.map(x=>x.k),y:c.by_k.map(x=>x.stability),line:{color:GOLD,width:2,dash:'dot'},marker:{size:6,color:GOLD}}],{height:330,showlegend:true,legend:{orientation:'h',y:1.08,x:0,font:{size:9}},xaxis:{title:{text:'Number of groups',font:{size:9}},dtick:1,showgrid:false},yaxis:{title:{text:'Silhouette',font:{size:9}},gridcolor:'#edf0e8',zeroline:false},yaxis2:{overlaying:'y',side:'right',range:[0,1],tickformat:'.0%',showgrid:false,title:{text:'Stability',font:{size:9}}},margin:{l:55,r:55,t:30,b:45}});
$('clusterRows').innerHTML=c.profiles.map((p,i)=>`<tr><td><span class="cluster-dot" style="background:${CLUSTER_COLORS[i]}"></span>${esc(p.name)}</td><td>${num(p.customers)} · ${pct(p.share_customers,0)}</td><td>${pct(p.share_spend,0)}</td><td>${num(p.recency)}</td><td>${num(p.orders)}</td><td>${money(p.spend)}</td><td>${money(p.average_order)}</td><td>${num(p.tenure)}</td></tr>`).join('');}
/* Inspectable SQL, sources and download helpers. */
let activeQuery='01_ledger.sql',drawerQuery='10_summary.sql',previousFocus;
function highlightSQL(s){const tokens=s.match(/--[^\n]*|'(?:''|[^'])*'|\b(?:SELECT|FROM|WHERE|WITH|AS|CASE|WHEN|THEN|ELSE|END|GROUP|BY|ORDER|JOIN|LEFT|ON|AND|OR|NOT|NULL|IS|CREATE|REPLACE|TABLE|DISTINCT|OVER|PARTITION|UNION|ALL|LIMIT|INTERVAL|TIMESTAMP|DESC|USING|DOUBLE)\b|[^'-]+?|./gsi)||[];return tokens.map(t=>t.startsWith('--')?`<span class="sql-comment">${esc(t)}</span>`:t.startsWith("'")?`<span class="sql-string">${esc(t)}</span>`:/^(SELECT|FROM|WHERE|WITH|AS|CASE|WHEN|THEN|ELSE|END|GROUP|BY|ORDER|JOIN|LEFT|ON|AND|OR|NOT|NULL|IS|CREATE|REPLACE|TABLE|DISTINCT|OVER|PARTITION|UNION|ALL|LIMIT|INTERVAL|TIMESTAMP|DESC|USING|DOUBLE)$/i.test(t)?`<span class="sql-keyword">${esc(t)}</span>`:esc(t)).join('');}
function renderData(){$('qualityChecks').innerHTML=D.checks.map(c=>`<div class="quality-row"><span>${esc(c.check_name)}</span><strong>${num(c.value)}</strong></div>`).join('');$('queryList').innerHTML=Object.keys(D.sql).map(k=>`<button class="query-button ${k===activeQuery?'active':''}" data-query="${esc(k)}">${esc(k)}</button>`).join('');showQuery(activeQuery);}
function showQuery(k){activeQuery=k;$('queryFilename').textContent=k;$('librarySql').innerHTML=highlightSQL(D.sql[k]);document.querySelectorAll('[data-query]').forEach(b=>b.classList.toggle('active',b.dataset.query===k));}
$('queryList').addEventListener('click',e=>{const b=e.target.closest('[data-query]');if(b)showQuery(b.dataset.query);});
function openSql(k){if(!D.sql[k])return;drawerQuery=k;previousFocus=document.activeElement;$('drawerFilename').textContent=k;$('drawerSql').innerHTML=highlightSQL(D.sql[k]);$('sqlOverlay').hidden=false;document.body.style.overflow='hidden';$('closeSql').focus();}
function closeSql(){$('sqlOverlay').hidden=true;document.body.style.overflow='';previousFocus?.focus();}
$('closeSql').addEventListener('click',closeSql);document.querySelector('.drawer-backdrop').addEventListener('click',closeSql);
$('sqlOverlay').addEventListener('keydown',e=>{if(e.key==='Escape')closeSql();if(e.key==='Tab'){const a=$('sqlOverlay').querySelectorAll('button'),first=a[1],last=a[a.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
async function copySql(k){try{await navigator.clipboard.writeText(D.sql[k]);toast('SQL copied to clipboard.');}catch{toast('Select the visible SQL and copy it with your keyboard.');}}
$('copyDrawerSql').addEventListener('click',()=>copySql(drawerQuery));$('copyLibrarySql').addEventListener('click',()=>copySql(activeQuery));
function downloadCSV(name,rows){if(!rows.length){toast('No rows to export.');return;}const keys=Object.keys(rows[0]);const cell=x=>{let s=String(x??'');if(typeof x==='string'&&/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const csv=[keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n'),url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exported '+num(rows.length)+' rows.');}
$('exportBtn').addEventListener('click',()=>{if(state.view==='overview')downloadCSV('meridian-daily-'+state.period+'-'+state.market,current().daily);else if(state.view==='customers')downloadCSV('meridian-customers',filteredCustomers());else if(state.view==='models'){const m=D.models[state.model];downloadCSV('meridian-model-evaluation',m.actual.map((v,i)=>({evaluation_row:i+1,actual_repeat:v,score:m.scores[i],predicted_repeat:m.scores[i]>=state.threshold?1:0,threshold:state.threshold})));}else if(state.view==='affinity')downloadCSV('meridian-product-pairs',D.affinity.top);else if(state.view==='forecast')downloadCSV('meridian-forecast',D.forecast.rows);else if(state.view==='regression')downloadCSV('meridian-spend-deciles',D.regression.deciles);else if(state.view==='clusters')downloadCSV('meridian-cluster-profiles',D.clusters.profiles);else downloadCSV('meridian-data-checks',D.checks);});
/* Small keyboard-first command palette. */
const command=$('commandDialog');let commandIndex=0,commands=[];function renderCommands(){const q=$('commandInput').value.toLowerCase();commands=Object.entries(HEADERS).filter(([k,v])=>(k+' '+v[3]).toLowerCase().includes(q));commandIndex=Math.min(commandIndex,commands.length-1);$('commandResults').innerHTML=commands.map(([k,v],i)=>`<button class="command-result ${i===commandIndex?'selected':''}" data-command="${k}">${esc(v[3])}<span>↵</span></button>`).join('')||'<div class="command-result">No matching views</div>';}
function openCommand(){command.showModal();$('commandInput').value='';commandIndex=0;renderCommands();$('commandInput').focus();}
$('commandOpen').addEventListener('click',openCommand);$('commandInput').addEventListener('input',()=>{commandIndex=0;renderCommands();});$('commandInput').addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();commandIndex=(commandIndex+(e.key==='ArrowDown'?1:-1)+commands.length)%commands.length;renderCommands();}if(e.key==='Enter'){e.preventDefault();if(commands[commandIndex]){showView(commands[commandIndex][0]);command.close();}}});$('commandResults').addEventListener('click',e=>{const b=e.target.closest('[data-command]');if(b){command.close();showView(b.dataset.command);}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();command.open?command.close():openCommand();}});
window.addEventListener('hashchange',()=>showView(location.hash.slice(1),false));window.addEventListener('resize',()=>{document.querySelectorAll('.view.active .js-plotly-plot').forEach(el=>Plotly.Plots.resize(el));});
showView(HEADERS[location.hash.slice(1)]?location.hash.slice(1):'overview',false);
// Minimal read-only diagnostics for automated integrity checks; no eval or browser SQL execution.
window.MERIDIAN={getState:()=>({...state,selected:state.selected?[...state.selected]:null}),confusion,modelMetrics:D.models,source:D.source};
})();
